// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');

const { fontFamily: oswaldFamily } = loadOswald();



export type TheoryOfConstraintsProps = Record<string, any>;

const TheoryOfConstraints: React.FC<TheoryOfConstraintsProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = false,
  centerCircleColor = "#ffffff",
  durationInSeconds = 4, // Included for schema compliance, though Remotion Composition defines actual duration
  title = "THEORY OF CONSTRAINTS",
  subtitle = "Five Focusing Steps",
  segments = [
    { label: "IDENTIFY", colorStart: "#3ebaf1", colorEnd: "#2486d3" },
    { label: "EXPLOIT", colorStart: "#8d3b9e", colorEnd: "#67217c" },
    { label: "SUBORDINATE", colorStart: "#ec2d8f", colorEnd: "#b01c69" },
    { label: "ELEVATE", colorStart: "#fbad18", colorEnd: "#e08611" },
    { label: "REPEAT", colorStart: "#a5c13b", colorEnd: "#759124" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;
  const holeColor = transparentBackground
    ? `${centerCircleColor}00`
    : centerCircleColor;

  const N = segments.length;
  // Add a 1 degree overlap to prevent hairline rendering gaps between SVG paths
  const wedgeSpan = 360 / N + 1;
  const textSpan = 360 / N - 4;

  const innerR = 140;
  const outerR = 400;
  const textR = 250;
  const fontSize = Math.min(56, 280 / N);

  const getWedgePath = (span: number) => {
    const h = (span / 2) * (Math.PI / 180);
    const x1 = Math.cos(-h) * outerR;
    const y1 = Math.sin(-h) * outerR;
    const x2 = Math.cos(h) * outerR;
    const y2 = Math.sin(h) * outerR;
    const la = span > 180 ? 1 : 0;
    // Drawing a full pie slice; the center is covered by the white hole circle later
    return `M 0 0 L ${x1} ${y1} A ${outerR} ${outerR} 0 ${la} 1 ${x2} ${y2} Z`;
  };

  const getTextArc = (span: number) => {
    const h = (span / 2) * (Math.PI / 180);
    const tx1 = Math.cos(-h) * textR;
    const ty1 = Math.sin(-h) * textR;
    const tx2 = Math.cos(h) * textR;
    const ty2 = Math.sin(h) * textR;
    const la = span > 180 ? 1 : 0;
    return `M ${tx1} ${ty1} A ${textR} ${textR} 0 ${la} 1 ${tx2} ${ty2}`;
  };

  const wedgePathStr = getWedgePath(wedgeSpan);
  const textArcStr = getTextArc(textSpan);
  const arcId = "textArc-wheel";

  // Calculate target angles and reverse drawing order for correct physical overlap
  const parsedSegments = segments.map((seg, i) => ({
    ...seg,
    targetAngle: -90 + i * (360 / N),
    originalIndex: i,
  }));
  const drawnSegments = [...parsedSegments].reverse();

  // Animations
  const titleOpacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [5, 20], [180, 230], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const wheelScale = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, mass: 0.9 },
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: oswaldFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          position: "absolute",
          width: "100%",
          top: titleY,
          opacity: titleOpacity,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
          padding: "0 40px",
        }}
      >
        <div
          style={{
            fontSize: 90,
            fontWeight: 700,
            color: "#333333",
            lineHeight: 1,
            letterSpacing: "-0.01em",
          }}
        >
          {title.toUpperCase()}
        </div>
        <div
          style={{
            fontSize: 50,
            fontWeight: 400,
            color: "#888888",
            marginTop: 10,
          }}
        >
          {subtitle}
        </div>
      </div>

      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          overflow: "visible",
        }}
      >
        <defs>
          <path id={arcId} d={textArcStr} />
          {segments.map((seg, i) => (
            <linearGradient
              key={`grad-${i}`}
              id={`grad-${i}`}
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stopColor={seg.colorStart} />
              <stop offset="100%" stopColor={seg.colorEnd} />
            </linearGradient>
          ))}
        </defs>

        <g
          transform={`translate(${width / 2}, ${height * 0.55}) scale(${wheelScale})`}
        >
          {drawnSegments.map((seg) => {
            // Stagger the fan-out animation sequentially from the top wedge downward
            const delay = 15 + seg.originalIndex * 6;
            const rotProgress = spring({
              frame: frame - delay,
              fps,
              config: { damping: 15, mass: 0.8 },
            });
            const currentAngle = interpolate(
              rotProgress,
              [0, 1],
              [-90, seg.targetAngle]
            );

            return (
              <g key={seg.label} transform={`rotate(${currentAngle})`}>
                <path
                  d={wedgePathStr}
                  fill={`url(#grad-${seg.originalIndex})`}
                />
                <text
                  fill="white"
                  fontSize={fontSize}
                  fontWeight="700"
                  fontFamily={oswaldFamily}
                  letterSpacing="0.05em"
                >
                  <textPath
                    href={`#${arcId}`}
                    startOffset="50%"
                    textAnchor="middle"
                  >
                    {seg.label}
                  </textPath>
                </text>
              </g>
            );
          })}
          <circle cx={0} cy={0} r={innerR} fill={holeColor} />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default TheoryOfConstraints;